import { Data, Effect } from "effect"

export interface Invoice {
  readonly id: string
  readonly totalCents: number
}

export interface Shipment {
  readonly id: string
  readonly weightGrams: number
}

export interface Quote {
  readonly carrier: string
  readonly priceCents: number
}

export class RenderError extends Data.TaggedError("RenderError")<{
  readonly message: string
}> {}

export class RateError extends Data.TaggedError("RateError")<{
  readonly message: string
}> {}

export interface Providers {
  readonly renderInvoice: (invoice: Invoice) => Effect.Effect<Uint8Array, RenderError>
  readonly quoteShipment: (shipment: Shipment) => Effect.Effect<Quote, RateError>
}

const memoize = <I, A, E>(
  keyOf: (input: I) => string,
  load: (input: I) => Effect.Effect<A, E>
) => {
  const values = new Map<string, A>()
  return (input: I): Effect.Effect<A, E> => Effect.suspend(() => {
    const key = keyOf(input)
    const cached = values.get(key)
    if (cached !== undefined) return Effect.succeed(cached)
    return load(input).pipe(
      Effect.tap((value) => Effect.sync(() => { values.set(key, value) }))
    )
  })
}

export const makeFulfillmentCaches = (providers: Providers) => {
  const invoicePdfs = memoize(
    (invoice: Invoice) => invoice.id,
    providers.renderInvoice
  )
  const shippingQuotes = memoize(
    (shipment: Shipment) => shipment.id,
    providers.quoteShipment
  )

  return { invoicePdfs, shippingQuotes }
}
